<?php
require_once __DIR__ . '/helpers.php'; if(session_status()===PHP_SESSION_NONE)session_start(); if(empty($_SESSION['user_id']))respond(['error'=>'Chưa đăng nhập.'],401);
function ensure_duyet_giao_an_sessions(PDO $pdo):void{$pdo->exec("CREATE TABLE IF NOT EXISTS duyet_giao_an_sessions (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,dot_duyet VARCHAR(80) NOT NULL DEFAULT '',thang VARCHAR(30) NOT NULL DEFAULT '',nam_hoc VARCHAR(30) NOT NULL DEFAULT '',to_chuyen_mon VARCHAR(255) NOT NULL DEFAULT '',summary TEXT NOT NULL,session_data LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_duyet_giao_an_user (user_id),INDEX idx_duyet_giao_an_updated (updated_at)) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");}
$userId=(int)$_SESSION['user_id'];$method=$_SERVER['REQUEST_METHOD']??'GET';$action=$_GET['action']??'';try{ensure_duyet_giao_an_sessions($pdo);if($method==='GET'&&$action==='list'){$s=$pdo->prepare('SELECT id,dot_duyet,thang,nam_hoc,to_chuyen_mon,summary,created_at,updated_at FROM duyet_giao_an_sessions WHERE user_id=? ORDER BY updated_at DESC');$s->execute([$userId]);respond(['ok'=>true,'sessions'=>$s->fetchAll()]);}if($method==='GET'&&isset($_GET['id'])){$s=$pdo->prepare('SELECT * FROM duyet_giao_an_sessions WHERE id=? AND user_id=?');$s->execute([(int)$_GET['id'],$userId]);$row=$s->fetch();if(!$row)respond(['error'=>'Không tìm thấy đợt duyệt.'],404);$row['session_data']=json_decode($row['session_data'],true);respond(['ok'=>true,'session'=>$row]);}if($method==='POST'&&$action==='delete'){$b=json_body();$s=$pdo->prepare('DELETE FROM duyet_giao_an_sessions WHERE id=? AND user_id=?');$s->execute([(int)($b['id']??0),$userId]);respond(['ok'=>true]);}if($method==='POST'){$b=json_body();$data=$b['session_data']??null;if(!is_array($data))respond(['error'=>'Dữ liệu đợt duyệt không hợp lệ.'],422);$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$values=[trim((string)($b['dot_duyet']??'')),trim((string)($b['thang']??'')),trim((string)($b['nam_hoc']??'')),trim((string)($b['to_chuyen_mon']??'')),trim((string)($b['summary']??'')),$json];$id=(int)($b['id']??0);if($id){$exists=$pdo->prepare('SELECT 1 FROM duyet_giao_an_sessions WHERE id=? AND user_id=?');$exists->execute([$id,$userId]);if(!$exists->fetchColumn())respond(['error'=>'Không tìm thấy đợt duyệt.'],404);$s=$pdo->prepare('UPDATE duyet_giao_an_sessions SET dot_duyet=?,thang=?,nam_hoc=?,to_chuyen_mon=?,summary=?,session_data=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?');$s->execute([...$values,$id,$userId]);}else{$s=$pdo->prepare('INSERT INTO duyet_giao_an_sessions(user_id,dot_duyet,thang,nam_hoc,to_chuyen_mon,summary,session_data)VALUES(?,?,?,?,?,?,?)');$s->execute([$userId,...$values]);$id=(int)$pdo->lastInsertId();}$s=$pdo->prepare('SELECT id,dot_duyet,thang,nam_hoc,to_chuyen_mon,summary,created_at,updated_at FROM duyet_giao_an_sessions WHERE id=?');$s->execute([$id]);respond(['ok'=>true,'session'=>$s->fetch()]);}respond(['error'=>'Method not allowed.'],405);}catch(Throwable $e){respond(['error'=>'Không thể lưu lịch sử duyệt.'],500);}
